void reset_signal_handlers(struct task_struct *t, int force_default) {
    int sig;

    for (sig = 1; sig < MAX_SIG; sig++) {
        if (force_default || t->signal_handlers[sig].action != SIG_IGN) {
            t->signal_handlers[sig].action = SIG_DFL;
            t->signal_handlers[sig].flags = 0;
            sigemptyset(&t->signal_handlers[sig].mask);
        }
    }
}

void flush_signal_handlers(struct task_struct *t, int force_default) {
    int sig;

    for (sig = 1; sig < _NSIG; sig++) {
        if (force_default || !sigismember(&t->blocked, sig)) {
            t->sighand[sig].sa_handler = SIG_DFL;
            sigemptyset(&t->sighand[sig].sa_mask);
            t->sighand[sig].sa_flags = 0;
        }
    }
}

void reset_signal_handlers_to_default(struct task_struct *t, int force_default) {
